  async function applyLibraryTemplate(id){
    collectDraft();
    const item=R.templateLibrary.find(t=>String(t.id)===String(id));
    if(!item||item.archived)throw new Error('Ten szablon jest zarchiwizowany lub niedostępny. Odśwież bibliotekę.');
    const s=R.campaign.state,key=templateKey(item.id);
    if(s.template_scenes[key]&&!(await askConfirm('Zastosować szablon ponownie?','Zastąpi to poprawki tego szablonu w bieżącej kampanii. Inne układy pozostaną bez zmian.','Zastosuj')))return;
    const instance=templateInstance(item);R.undo.push(snapshotSceneState());if(R.undo.length>30)R.undo.shift();
    s.applied_templates=s.applied_templates||{};s.applied_templates[key]={name:item.name,base_template:item.recipe.base_template};
    s.template_scenes[key]=instance.master;
    for(const old of Object.keys(s.scenes))if(old.startsWith(key+':'))delete s.scenes[old];
    for(const [format,scene] of Object.entries(instance.formats))s.scenes[key+':'+format]=scene;
    s.template=key;s.scene=clone(instance.master);s.selected_templates=[...new Set([...s.selected_templates,key])];
    R.editorFormat='master';R.libraryOpen=false;marked();renderCampaign();
    notify(instance.missing.length?'Zastosowano szablon. Uzupełnij brakujące materiały wskazane pod edytorem.':instance.warnings?.length?instance.warnings.join(' '):'Zastosowano układ do materiałów i tekstów tej kampanii.',Boolean(instance.missing.length));
  }
